187	// free the heap resources (assuming the pages are already moved/destroyed, and all theaps have been freed)
188	static void mi_heap_free(mi_heap_t* heap, bool acquire_heaps_lock) {
189	  mi_assert_internal(heap!=NULL); // && !_mi_is_process_heap_main(heap));
190	
191	  // free all arena pages infos
192	  const bool is_main = _mi_is_heap_main(heap);
193	  if (!is_main) {  // pages for the main heap are pre-allocated in the arenas
194	    mi_lock(&heap->arena_pages_lock) {
195	      for (size_t i = 0; i < MI_MAX_ARENAS; i++) {
196	        mi_arena_pages_t* arena_pages = mi_atomic_load_ptr_relaxed(mi_arena_pages_t, &heap->arena_pages[i]);
197	        if (arena_pages!=NULL) {
198	          mi_atomic_store_ptr_relaxed(mi_arena_pages_t, &heap->arena_pages[i], NULL);
199	          _mi_free_subproc_safe(arena_pages);
200	        }
201	      }
202	    }
203	  }
204	
205	  // remove the heap from the subproc
206	  if (!is_main) { 
207	    mi_heap_stats_merge_to_main(heap); 
208	  }
209	  else {
210	    _mi_stats_merge_into(&heap->subproc->stats,&heap->stats);
211	  }
212	  mi_atomic_decrement_relaxed(&heap->subproc->heap_count);
213	  mi_subproc_stat_decrease(heap->subproc, heaps, 1);
214	  mi_lock_maybe(&heap->subproc->heaps_lock, acquire_heaps_lock) {
215	    if (heap->next!=NULL) { heap->next->prev = heap->prev; }
216	    if (heap->prev!=NULL) { heap->prev->next = heap->next; }
217	                     else { heap->subproc->heaps = heap->next; }
218	  }
219	
220	  mi_lock_done(&heap->theaps_lock);
221	  mi_lock_done(&heap->os_abandoned_pages_lock);
222	  mi_lock_done(&heap->arena_pages_lock);
223	  if (!_mi_is_process_heap_main(heap)) { 
224	    _mi_thread_local_free(heap->theap);
225	    _mi_free_subproc_safe(heap); 
226	  }
227	}
