141	static mi_subproc_t* mi_subproc_init(mi_subproc_t* subproc, mi_subproc_t* parent) {
142	  static _Atomic(size_t) subproc_total_count;
143	  subproc->parent = parent;
144	  subproc->subproc_seq = mi_atomic_increment_relaxed(&subproc_total_count);
145	  mi_stats_header_init(&subproc->stats);
146	  mi_lock_init(&subproc->arena_reserve_lock);
147	  mi_lock_init(&subproc->heaps_lock);
148	  mi_lock_init(&subproc->theap_meta_lock);
149	  mi_lock(&mi_subprocs_lock) {
150	    // push on subproc list
151	    subproc->next = mi_subprocs;
152	    if (mi_subprocs!=NULL) { mi_subprocs->prev = subproc; }
153	    mi_subprocs = subproc;
154	  }
155	  return subproc;
156	}
