161	  mi_memid_t memid;
162	  mi_subproc_t* const subproc = (mi_subproc_t*)_mi_meta_zalloc(parent, sizeof(mi_subproc_t), &memid);
163	  if (subproc == NULL) { return _mi_subproc_to_id(NULL); }
164	  subproc->memid  = memid;  
165	  
166	  mi_memid_t theap_memid;
167	  mi_theap_t* const theap_meta = (mi_theap_t*)_mi_meta_zalloc(parent, sizeof(mi_theap_t), &theap_memid);
168	  if (theap_meta==NULL) { 
169	    _mi_meta_free(parent, subproc, memid); 
170	    return _mi_subproc_to_id(NULL); 
171	  }
172	  theap_meta->memid = memid;
173	  
174	  // init subproc
175	  mi_subproc_init(subproc,parent);
176	  
177	  // init main heap
178	  mi_heap_t* heap_main = _mi_heap_new_for_subproc(subproc,0,true);
179	  if (heap_main==NULL) {
180	    _mi_meta_free(parent, theap_meta, theap_meta->memid);
181	    mi_subproc_destroy(_mi_subproc_to_id(subproc));
182	    return _mi_subproc_to_id(NULL);
183	  }
184	  mi_assert_internal(subproc->heap_main == heap_main);
185	
186	  // init meta theap
187	  mi_assert_internal(parent->theap_meta!=NULL);
188	  mi_assert_internal(parent->theap_meta->tld!=NULL);
189	  mi_assert_internal(parent->theap_meta->tld->thread_id == MI_THREADID_DETACHED);
190	  _mi_theap_init(theap_meta,heap_main,parent->theap_meta->tld /* detached tld */);
191	  subproc->theap_meta = theap_meta;
192	
193	  return _mi_subproc_to_id(subproc);
194	}
195	
