197	/* -----------------------------------------------------------
198	  Sub process destruction
199	----------------------------------------------------------- */
200	
201	// destroy all subproc resources including arena's, heap's etc.
202	static void mi_subproc_unsafe_destroy(mi_subproc_t* subproc, bool acquire_subprocs_lock)
203	{
204	  if (subproc==NULL) return;
205	
206	  // remove from the subproc list
207	  mi_lock_maybe(&mi_subprocs_lock, acquire_subprocs_lock) {
208	    if (subproc->next!=NULL) { subproc->next->prev = subproc->prev;  }
209	    if (subproc->prev!=NULL) { subproc->prev->next = subproc->next;  }
210	                        else { mi_assert_internal(mi_subprocs==subproc);  mi_subprocs = subproc->next; }
211	  }
212	
213	  // destroy all subproc heaps
214	  mi_lock(&subproc->heaps_lock) {
215	    mi_heap_t* heap = subproc->heaps;
216	    while (heap != NULL) {
217	      mi_heap_t* next = heap->next;
218	      if (heap!=subproc->heap_main) { _mi_heap_force_destroy(heap, false /* don't re-acquire the heaps_lock */); }
219	      heap = next;
220	    }
221	    mi_assert_internal(subproc->heap_main==NULL || subproc->heaps == subproc->heap_main);
222	    if (subproc->heap_main!=NULL) {
223	      _mi_thread_locals_thread_done(); // release thread locals that may have been allocated (safe as the main heap uses the fast key)
224	      if (_mi_subproc_is_main(subproc)) {
225	        _mi_thread_locals_done();      
226	      }
227	      _mi_heap_force_destroy(subproc->heap_main, false /* don't re-acquire the heaps_lock */);  // no warning if destroying the main heap
228	    }
229	  }
230	
231	  subproc->theap_meta = NULL; // theap meta stats are merged during heap_destroy of the main heap
232	
233	  if (!_mi_subproc_is_main(subproc)) {
234	    // merge stats back into the main subproc  
235	    _mi_stats_merge_into(&mi_process_subproc_main.stats, &subproc->stats);
236	  }
237	
238	  // remove associated arenas
239	  _mi_arenas_unsafe_destroy_all(subproc);
240	
241	  // show stats of the main process (at process end) before releasing the heaps lock
242	  if (_mi_subproc_is_main(subproc)) {
243	    if (mi_option_is_enabled(mi_option_show_stats) || mi_option_is_enabled(mi_option_verbose)) {
244	      mi_subproc_stats_print_out(mi_subproc_main(), NULL, NULL);
245	    }
246	  }
247	
248	  // todo: should we refcount subprocesses?
249	  mi_lock_done(&subproc->arena_reserve_lock);
250	  mi_lock_done(&subproc->heaps_lock);

