37	    mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
38	  }
39	
40	  // check the free list
41	  mi_block_t* const block = page->free;
42	  const mi_used_t used = page->used;
43	  #if defined(__GNUC__) 
